CREATE TABLE "DiscountRule" ("id" TEXT NOT NULL PRIMARY KEY, "shop" TEXT NOT NULL, "title" TEXT NOT NULL, "enabled" BOOLEAN NOT NULL DEFAULT true, "priority" INTEGER NOT NULL DEFAULT 0, "targetType" TEXT NOT NULL, "internalNotes" TEXT NOT NULL DEFAULT '', "startsAt" DATETIME, "endsAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "DiscountTarget" ("id" TEXT NOT NULL PRIMARY KEY, "shopifyId" TEXT NOT NULL, "label" TEXT NOT NULL DEFAULT '', "ruleId" TEXT NOT NULL, CONSTRAINT "DiscountTarget_ruleId_fkey" FOREIGN KEY ("ruleId") REFERENCES "DiscountRule" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "DiscountTier" ("id" TEXT NOT NULL PRIMARY KEY, "minimum" INTEGER NOT NULL, "maximum" INTEGER, "title" TEXT NOT NULL DEFAULT '', "discountType" TEXT NOT NULL, "discountValue" DECIMAL, "message" TEXT NOT NULL DEFAULT '', "ruleId" TEXT NOT NULL, CONSTRAINT "DiscountTier_ruleId_fkey" FOREIGN KEY ("ruleId") REFERENCES "DiscountRule" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "DiscountRule_shop_enabled_priority_idx" ON "DiscountRule"("shop", "enabled", "priority");
CREATE UNIQUE INDEX "DiscountTarget_ruleId_shopifyId_key" ON "DiscountTarget"("ruleId", "shopifyId");
CREATE UNIQUE INDEX "DiscountTier_ruleId_minimum_key" ON "DiscountTier"("ruleId", "minimum");
CREATE INDEX "DiscountTier_ruleId_minimum_idx" ON "DiscountTier"("ruleId", "minimum");
